# illustrative (NOT in repo): chunked AES-GCM wrapper in the same style as HashingStream
from cryptography.hazmat.primitives.ciphers.aead import AESGCM

class EncryptingStream:
    CHUNK = 64 * 1024
    def __init__(self, source, dek: bytes, object_nonce: bytes):
        self.source, self.aes, self.nonce = source, AESGCM(dek), object_nonce
    async def __aiter__(self):
        buf, idx = b"", 0
        async for chunk in self.source:
            buf += chunk
            while len(buf) >= self.CHUNK:
                yield self._seal(buf[:self.CHUNK], idx); buf, idx = buf[self.CHUNK:], idx + 1
        if buf:
            yield self._seal(buf, idx)
    def _seal(self, data, idx):
        return self.aes.encrypt(self.nonce[:8] + idx.to_bytes(4, "big"), data, None)

